class _HierarchieIntroPageState extends State<HierarchieIntroPage>
    with TickerProviderStateMixin {
  // === EDITABLE — CONFIG ===
  // Change l’image si besoin (par ex.

;
  static const Alignment _kBackgroundAlignment = Alignment(0, -0.50);
  static const BoxFit _kFit = BoxFit.cover;

  // Cible : ta page contenu existante
  static const String _kTargetRouteName = HierarchieContenuPage.routeName;

  // Animations
  late final AnimationController _fadeCtrl = AnimationController(
    vsync: this,
    duration: const Duration(milliseconds: 1100),
  )..forward();

  late final AnimationController _subtitleCtrl = AnimationController(
    vsync: this,
    duration: const Duration(milliseconds: 900),
  );

  late final AnimationController _buttonPulseCtrl = AnimationController(
    vsync: this,
    duration: const Duration(milliseconds: 1300),
    lowerBound: 0.0,
    upperBound: 1.0,
  )..repeat(reverse: true);

  // Écriture IA (typewriter)
  static const String _titleFull =

;
  int _typedCount = 0;
  Timer? _typeTimer;

  @override
  void initState() {
    super.initState();
    _typeTimer = Timer.periodic(const Duration(milliseconds: 36), (t) {
      if (!mounted) return;
      if (_typedCount < _titleFull.length) {
        setState(() => _typedCount++);
      } else {
        t.cancel();
        _subtitleCtrl.forward();
      }
    });
  }

  @override
  void dispose() {
    _typeTimer?.cancel();
    _fadeCtrl.dispose();
    _subtitleCtrl.dispose();
    _buttonPulseCtrl.dispose();
    super.dispose();
  }

  Future<void> _onStart() async {
    if (!mounted) return;
    await Navigator.of(context).push(
      PageRouteBuilder(
        transitionDuration: const Duration(milliseconds: 420),
        pageBuilder: (context, animation, secondaryAnimation) {
          return const _RouteShimToTarget();
        },
        transitionsBuilder: (context, animation, secondary, child) {
          return FadeTransition(
            opacity: CurvedAnimation(
              parent: animation,
              curve: Curves.easeOutCubic,
            ),
            child: child,
          );
        },
      ),
    );
  }

  @override
  Widget build(BuildContext context) {
    const bgColor = Color(0xFF070707);

    return Scaffold(
      backgroundColor: bgColor,
      body: Stack(
        fit: StackFit.expand,
        children: [
          // 1) Image de fond
          AnimatedBuilder(
            animation: _fadeCtrl,
            builder: (context, _) {
              return Opacity(
                opacity: CurvedAnimation(
                  parent: _fadeCtrl,
                  curve: Curves.easeOut,
                ).value,
                child: Image.asset(
                  _kBackgroundPath,
                  fit: _kFit,
                  alignment: _kBackgroundAlignment,
                  filterQuality: FilterQuality.high,
                ),
              );
            },
          ),

          // 2) Voile lisibilité
          const DecoratedBox(
            decoration: BoxDecoration(
              gradient: LinearGradient(
                begin: Alignment.topCenter,
                end: Alignment.bottomCenter,
                colors: [Color(0x99000000), Color(0xD0000000)],
              ),
            ),
          ),

          // 3) Contenu centré
          SafeArea(
            child: Padding(
              padding: const EdgeInsets.symmetric(horizontal: 24),
              child: Column(
                children: [
                  const Spacer(),

                  // Titre typewriter
                  _TypewriterTitle(text: _titleFull.substring(0, _typedCount)),

                  const SizedBox(height: 14),

                  // Sous-texte (après fin titre)
                  FadeTransition(
                    opacity: CurvedAnimation(
                      parent: _subtitleCtrl,
                      curve: Curves.easeOutCubic,
                    ),
                    child: Text(
                      "Fonctions judiciaires et place de chacun dans la chaîne hiérarchique.
Idéal pour visualiser qui fait quoi, du gardien au directeur.",
                      textAlign: TextAlign.center,
                      style: GoogleFonts.fustat(
                        textStyle: const TextStyle(
                          fontSize: 16,
                          fontWeight: FontWeight.w500,
                          color: Colors.white70,
                        ),
                      ),
                    ),
                  ),

                  const SizedBox(height: 28),

                  // Bouton principal
                  _NeonButton(
                    label:

,
                    glow: _buttonPulseCtrl,
                    onTap: _onStart,
                  ),

                  const Spacer(),

                  // Indice de navigation minimal
                  Padding(
                    padding: const EdgeInsets.only(bottom: 12),
                    child: Icon(
                      Icons.keyboard_arrow_down_rounded,
                      color: Colors.white.withValues(alpha: 0.55),
                      size: 22,
                    ),
                  ),
                ],
              ),
            ),
          ),

          // 4) Bouton RETOUR (réutilisable)
          const CopiqHeroBackButton(),
