        children: [
          // 1) Image de fond
          AnimatedBuilder(
            animation: _fadeCtrl,
            builder: (context, _) {
              return Opacity(
                opacity: CurvedAnimation(
                  parent: _fadeCtrl,
                  curve: Curves.easeOut,
                ).value,
                child: Image.asset(
                  _kBackgroundPath,
